WITH unpacked AS (SELECT id, plan, effective_from, tier_limits, tier_prices, AGGREGATE(tier_prices, 0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ARRAY_MIN(tier_prices) AS lowest_price, TRANSFORM(tier_prices, (p, i) -> ROUND(p * tier_limits[i], 2)) AS tier_revenue_caps, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT DATE_TRUNC('QUARTER', effective_from) AS quarter_start, DATE_TRUNC('WEEK', effective_from) AS week_start, plan, PERCENTILE_APPROX(lowest_price, ARRAY(0.25, 0.5, 0.75)) AS lowest_price_quartiles, PERCENTILE_APPROX(entry_price, 0.9) AS entry_price_p90, COUNT(*) AS num_rows FROM unpacked GROUP BY CUBE (DATE_TRUNC('QUARTER', effective_from), DATE_TRUNC('WEEK', effective_from), plan) HAVING COUNT(*) < 1;
